"use strict";const assert=require("node:assert/strict");const {RULESET_VERSION,OUTCOMES,createBootstrapAuthorizationConsumptionGateSatisfaction}=require("./bootstrap-authorization-consumption-gate-satisfaction");
const auth=()=>({type:"INITIAL_GOVERNANCE_BOOTSTRAP_AUTHORIZATION_EVIDENCE",bootstrapAuthorizationId:"auth:1",governanceAct:"INITIAL_GOVERNANCE_BOOTSTRAP",principalRef:"principal:human",bindingId:"binding:1",sourceEventRef:"event:1",composedApprovalEvidenceId:"composed:1",bootstrapGateId:"gate:1",bootstrapGateRevision:"1",repositoryIdentity:"goceterziev-creator/2l1p-neural-travel-v9",targetPath:"config/gt63-machine/governance-lifecycle-issuer-scope-policy-v0.json",beforeStateId:"sha256:before",afterStateId:"sha256:after",oneTime:true,consumed:false,authority:"NONE"});
const gate=()=>({type:"INITIAL_GOVERNANCE_BOOTSTRAP_GATE",gateId:"gate:1",gateRevision:"1",governanceAct:"INITIAL_GOVERNANCE_BOOTSTRAP",repositoryIdentity:"goceterziev-creator/2l1p-neural-travel-v9",targetPath:"config/gt63-machine/governance-lifecycle-issuer-scope-policy-v0.json",beforeStateId:"sha256:before",afterStateId:"sha256:after",oneTime:true,status:"PENDING",gateEvidenceRef:"gate-evidence:1",authority:"NONE"});
function ledger(){const rows=[];return{findByAuthorizationId:id=>rows.filter(x=>x.bootstrapAuthorizationId===id),findByGateId:id=>rows.filter(x=>x.bootstrapGateId===id),commit:e=>{rows.push(JSON.parse(JSON.stringify(e)));return JSON.parse(JSON.stringify(e));},rows};}
function env(o={}){const l=o.ledger||ledger();return{component:createBootstrapAuthorizationConsumptionGateSatisfaction({bootstrapAuthorizationEvidencePort:()=>o.a||auth(),bootstrapGatePort:()=>o.g||gate(),consumptionLedger:l}),ledger:l};}
const req=(x={})=>({rulesetVersion:RULESET_VERSION,bootstrapAuthorizationId:"auth:1",bootstrapGateId:"gate:1",bootstrapGateRevision:"1",repositoryIdentity:"goceterziev-creator/2l1p-neural-travel-v9",targetPath:"config/gt63-machine/governance-lifecycle-issuer-scope-policy-v0.json",expectedBeforeStateId:"sha256:before",expectedAfterStateId:"sha256:after",...x});
const T=[];const test=(n,f)=>T.push([n,f]);
test("exact unconsumed authorization satisfies exact pending gate",()=>{const r=env().component.satisfy(req());assert.equal(r.outcome,OUTCOMES.SATISFIED);assert.equal(r.humanGateSatisfied,true);assert.equal(r.evidence.authorizationConsumed,true);});
test("caller continuation authority rejected",()=>assert.equal(env().component.satisfy({...req(),continuationAuthority:true}).outcome,OUTCOMES.REJECTED));
test("caller execution authority rejected",()=>assert.equal(env().component.satisfy({...req(),executionAuthority:true}).outcome,OUTCOMES.REJECTED));
test("already-consumed authorization is uncertain",()=>assert.equal(env({a:{...auth(),consumed:true}}).component.satisfy(req()).outcome,OUTCOMES.UNCERTAIN));
test("non-pending gate is uncertain",()=>assert.equal(env({g:{...gate(),status:"SATISFIED"}}).component.satisfy(req()).outcome,OUTCOMES.UNCERTAIN));
test("gate id drift stale",()=>assert.equal(env({a:{...auth(),bootstrapGateId:"gate:2"}}).component.satisfy(req()).outcome,OUTCOMES.STALE));
test("gate revision drift stale",()=>assert.equal(env({a:{...auth(),bootstrapGateRevision:"2"}}).component.satisfy(req()).outcome,OUTCOMES.STALE));
test("repository drift stale",()=>assert.equal(env({a:{...auth(),repositoryIdentity:"other/repo"}}).component.satisfy(req()).outcome,OUTCOMES.STALE));
test("target drift stale",()=>assert.equal(env({a:{...auth(),targetPath:"config/other.json"}}).component.satisfy(req()).outcome,OUTCOMES.STALE));
test("before-state drift stale",()=>assert.equal(env({a:{...auth(),beforeStateId:"sha256:old"}}).component.satisfy(req()).outcome,OUTCOMES.STALE));
test("after-state drift stale",()=>assert.equal(env({a:{...auth(),afterStateId:"sha256:other"}}).component.satisfy(req()).outcome,OUTCOMES.STALE));
test("same satisfaction idempotent",()=>{const e=env();const a=e.component.satisfy(req()),b=e.component.satisfy(req());assert.equal(a.outcome,OUTCOMES.SATISFIED);assert.equal(b.outcome,OUTCOMES.ALREADY_SATISFIED);assert.equal(a.evidence.gateSatisfactionEvidenceId,b.evidence.gateSatisfactionEvidenceId);});
test("same authorization cannot satisfy second gate",()=>{const e=env();assert.equal(e.component.satisfy(req()).outcome,OUTCOMES.SATISFIED);const g2={...gate(),gateId:"gate:2"},a2={...auth(),bootstrapGateId:"gate:2"};const x=createBootstrapAuthorizationConsumptionGateSatisfaction({bootstrapAuthorizationEvidencePort:()=>a2,bootstrapGatePort:()=>g2,consumptionLedger:e.ledger});assert.equal(x.satisfy(req({bootstrapGateId:"gate:2"})).outcome,OUTCOMES.CONFLICT);});
test("gate satisfaction creates no continuation execution or mutation authority",()=>{const r=env().component.satisfy(req());assert.equal(r.continuationAuthorityCreated,false);assert.equal(r.executionAuthorityCreated,false);assert.equal(r.mutationAuthorized,false);assert.equal(r.mutationPerformed,false);assert.equal(r.evidence.authority,"NONE");});
let passed=0;for(const[n,f]of T){f();passed++;console.log(`PASS ${n}`)}console.log(`RESULT ${passed}/${T.length} PASS`);
